 Object.keys(S).forEach(function(i){ var s = S[i]; if (s.ed !== 'regioes' || !s.reg) return; (porReg[s.reg] = porReg[s.reg] || []).push(i); });
 function dia(s){ var m = String(s.hora||'').match(/^(\d{1,2})\/(\d{1,2})$/); return m ? (+m[2])*100 + (+m[1]) : 0; }
 Object.keys(porReg).forEach(function(r){
  var ativos = porReg[r].filter(function(i){ return !S[i].velha; }).length;
  porReg[r].filter(function(i){ return S[i].velha && dia(S[i]) >= 1111; }).sort(function(a,b){ return dia(S[b]) - dia(S[a]); }).forEach(function(i){
   if (ativos < 5) { delete S[i].velha; delete S[i].velhaMotivo; ativos++; }
  });
 });
})();

